import{_ as t,o as e,c as r,a0 as o}from"./chunks/framework.veCcaNqE.js";const c=JSON.parse('{"title":"复杂示例 4：航班恢复分支定价 — 总览","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/examples/framework-example4.md","filePath":"zh-cn/examples/framework-example4.md"}'),d={name:"zh-cn/examples/framework-example4.md"};function l(h,a,i,n,s,m){return e(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="复杂示例-4-航班恢复分支定价-—-总览" tabindex="-1">复杂示例 4：航班恢复分支定价 — 总览 <a class="header-anchor" href="#复杂示例-4-航班恢复分支定价-—-总览" aria-label="Permalink to &quot;复杂示例 4：航班恢复分支定价 — 总览&quot;">​</a></h1><p><a href="/ospf/examples/framework-example4.html">English</a></p><h2 id="_1-概述" tabindex="-1">1. 概述 <a class="header-anchor" href="#_1-概述" aria-label="Permalink to &quot;1. 概述&quot;">​</a></h2><p>Demo4 是架构示例。<code>Application</code> 为空类，通用量示例可运行；上下文页面描述已经实现的契约，不宣称已经组装了完整生产模型。</p><h2 id="_2-上下文与依赖" tabindex="-1">2. 上下文与依赖 <a class="header-anchor" href="#_2-上下文与依赖" aria-label="Permalink to &quot;2. 上下文与依赖&quot;">​</a></h2><table tabindex="0"><thead><tr><th>上下文</th><th>职责</th><th>依赖</th></tr></thead><tbody><tr><td>任务与规则</td><td>任务数据、连接和业务规则</td><td>输入配置</td></tr><tr><td>机组、货物、旅客</td><td>资源与运输需求</td><td>任务及相应资源数据</td></tr><tr><td>航班串生成</td><td>搜索符合策略的航班串</td><td>任务、规则及资源上下文</td></tr><tr><td>航班串编译</td><td>将列编译为覆盖、容量与目标表达式</td><td>已生成航班串、相关业务管线</td></tr><tr><td>航班串选择</td><td>协调列选择与分支定价策略</td><td>生成与编译契约</td></tr></tbody></table><h2 id="_3-概念、集合与谓词" tabindex="-1">3. 概念、集合与谓词 <a class="header-anchor" href="#_3-概念、集合与谓词" aria-label="Permalink to &quot;3. 概念、集合与谓词&quot;">​</a></h2><p>领域词汇包括航班任务、连接、机组、货物、旅客和航班串（bunch）。谓词表达可行任务转移、资源兼容性及列的接纳条件。相应集合由各上下文定义，不把所有资源合成一个无归属的集合。</p><h2 id="_4-变量与中间值" tabindex="-1">4. 变量与中间值 <a class="header-anchor" href="#_4-变量与中间值" aria-label="Permalink to &quot;4. 变量与中间值&quot;">​</a></h2><p>航班串编译上下文拥有列使用量，并根据各列系数计算任务、飞机和连接相关表达式。航班串生成与选择描述服务及回调契约，不重复声明主问题变量；具体记号和定义域见各上下文子页。</p><h2 id="_5-断言、约束与目标" tabindex="-1">5. 断言、约束与目标 <a class="header-anchor" href="#_5-断言、约束与目标" aria-label="Permalink to &quot;5. 断言、约束与目标&quot;">​</a></h2><p>编译上下文提供任务、连接、飞机及相关资源的模型契约；启用旅客等业务管线时再加入对应约束与目标。顶层空的 <code>Application</code> 并不定义完整全局目标，不能把这些契约误写成已组装的统一求解模型。</p><h2 id="_6-算法与生命周期" tabindex="-1">6. 算法与生命周期 <a class="header-anchor" href="#_6-算法与生命周期" aria-label="Permalink to &quot;6. 算法与生命周期&quot;">​</a></h2><p>架构上的协作顺序为：构造业务策略，初始化对偶信息，生成航班串，编译主问题，再根据约化成本和分支策略继续迭代。通用量示例单独演示量类型与线性符号 API。</p><h2 id="_7-注册-→-构造-→-求解-→-分析" tabindex="-1">7. 注册 → 构造 → 求解 → 分析 <a class="header-anchor" href="#_7-注册-→-构造-→-求解-→-分析" aria-label="Permalink to &quot;7. 注册 → 构造 → 求解 → 分析&quot;">​</a></h2><p>子页分别说明可注册的符号、管线和回调。Kotlin 顶层 <code>Application</code> 是占位入口，因此这里描述上下文的组合方式，不提供一个并不存在的端到端求解调用链。</p><h2 id="_8-源码入口" tabindex="-1">8. 源码入口 <a class="header-anchor" href="#_8-源码入口" aria-label="Permalink to &quot;8. 源码入口&quot;">​</a></h2><ul><li><a href="https://github.com/fuookami/ospf-kotlin/tree/main/ospf-kotlin-example/src/main/fuookami/ospf/kotlin/example/framework_demo/demo4" target="_blank" rel="noreferrer">Kotlin Demo4 源码</a></li><li><a href="https://github.com/fuookami/ospf-rust/tree/main/ospf-rust-example/src/framework/demo4" target="_blank" rel="noreferrer">Rust Demo4 源码</a></li></ul><h2 id="_9-kotlin-rust-对照与设计决策" tabindex="-1">9. Kotlin/Rust 对照与设计决策 <a class="header-anchor" href="#_9-kotlin-rust-对照与设计决策" aria-label="Permalink to &quot;9. Kotlin/Rust 对照与设计决策&quot;">​</a></h2><p>Kotlin 与 Rust 均有相应框架示例目录，但不能由同名目录推断相同的顶层完成度。本文以 Kotlin 上下文契约为基准，明确区分架构组合与已经执行的全局模型。</p><h2 id="_10-上下文模型页面" tabindex="-1">10. 上下文模型页面 <a class="header-anchor" href="#_10-上下文模型页面" aria-label="Permalink to &quot;10. 上下文模型页面&quot;">​</a></h2><p><a href="./framework-example4/domain-models.html">打开上下文索引</a>，分别阅读任务、规则、机组、货物、旅客、航班串生成、航班串编译与航班串选择。</p><h2 id="_11-变更记录" tabindex="-1">11. 变更记录 <a class="header-anchor" href="#_11-变更记录" aria-label="Permalink to &quot;11. 变更记录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>版本</th><th>变更</th><th>原因</th></tr></thead><tbody><tr><td>1.1</td><td>统一中英文总览、数学记号和源码入口</td><td>与所属上下文模型保持一致</td></tr></tbody></table>',24)])])}const _=t(d,[["render",l]]);export{c as __pageData,_ as default};
